import{_ as a,o as t,c as s,a6 as i}from"./chunks/framework.CKIbuWFA.js";const u=JSON.parse('{"title":"Widget SDK・ゲートウェイ・オーバーレイの境界","description":"","frontmatter":{"title":"Widget SDK・ゲートウェイ・オーバーレイの境界","docId":"developer.overlays","translationKey":"developer.overlays","locale":"ja","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"99d3351859ddb3a3304133f062f68b8e3130416947fc40433dc9c6bffaf85f6a","translationRevision":"3e5aaa62172d452bd9ad0af01ce9b4aaba25806f41e2806d1164036a17268179","order":170},"headers":[],"relativePath":"ja/developer/overlays.md","filePath":"ja/developer/overlays.md","lastUpdated":1794611623000}'),d={name:"ja/developer/overlays.md"};function o(r,e,l,n,c,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="widget-sdk-gateway-and-overlay-boundaries" tabindex="-1">Widget SDK・ゲートウェイ・オーバーレイの境界 <a class="header-anchor" href="#widget-sdk-gateway-and-overlay-boundaries" aria-label="Permalink to &quot;Widget SDK・ゲートウェイ・オーバーレイの境界 {#widget-sdk-gateway-and-overlay-boundaries}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>ローカルプレビューと OBS 出力で描画を共有するウィジェットを作ります。インストール済み Vue ツールチェーンを使い、<a href="./events.html">イベント</a> を理解します。ローカルプレビューはゲートウェイやアカウント認証情報が不要です。ライブ出力には別途インストールする event-gateway プラグインと、ウィジェット範囲の認証情報が必要です。</p><h2 id="add-a-template" tabindex="-1">テンプレートを追加する <a class="header-anchor" href="#add-a-template" aria-label="Permalink to &quot;テンプレートを追加する {#add-a-template}&quot;">​</a></h2><ol><li><code>WidgetStage</code> 内に描画部を定義し、ビューポートではなく親に対してサイズを決めます。</li><li><code>src/widgets/sdk/template.ts</code> の <code>defineWidget</code> にスキーマ、新しいサンプル包み、<code>create(search, clock)</code> ファクトリーを渡します。</li><li><code>handleEnvelope</code>、<code>clear</code>、<code>dispose</code> と描画を実装したコントローラーを返します。渡された時計を使い、プレビューでサンプルを保持し、テストで時刻を進められるようにします。</li><li><code>sdk/templates.ts</code> に登録し、単独入口、ビルド設定、ゲートウェイルート許可リスト、パッケージ項目を追加します。登録だけでは公開 URL はできません。</li><li>エディターと単独バンドルで同じ <code>WidgetHost.vue</code> を使います。ローカルプレビューにゲートウェイ HTML を埋め込みません。</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> widgets</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> widgets</span></span></code></pre></div><p>テキストトークン、デザイン既定値、編集フィールドはテンプレートスキーマに置きます。デザインは JSON に直列化され、コピーした URL は検証済みスナップショットを含みます。後で保存し直した場合は新しい URL を OBS にコピーします。</p><h2 id="gateway-protocol" tabindex="-1">ゲートウェイのプロトコル <a class="header-anchor" href="#gateway-protocol" aria-label="Permalink to &quot;ゲートウェイのプロトコル {#gateway-protocol}&quot;">​</a></h2><p><code>src/widgets/shared/gateway-client.ts</code> が認証、購読、ハートビート、再接続、欠落報告を担当します。ウィジェットは TikTok に直接接続せず、正規のドメイン包みを受け取ります。エンドポイントは <code>/ws/widgets</code> で、完全な外部ゲートウェイクライアント API とは異なります。共有パーサーを使い、完全なゲートウェイトークンをメイン WebView に渡さず認証境界を守ります。</p><h2 id="expected-result-and-status" tabindex="-1">期待される結果と提供状況 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;期待される結果と提供状況 {#expected-result-and-status}&quot;">​</a></h2><p>組み込みローカルプレビューと SDK は実装済みです。Cloud オーバーレイ編集と <code>cloud-overlay</code> のソースはありますが、実際の OBS 検証、画像・ライブソースの対応範囲、パッケージ適用には制限があります。オーバーレイの変更は未マージの別作業です。ランキングウィジェットがあってもランキングとコンテストは通常のナビゲーションから隠されています。</p><h2 id="recovery" tabindex="-1">問題が起きたとき <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;問題が起きたとき {#recovery}&quot;">​</a></h2><p>ローカルプレビューが空ならオリジン方針を弱める前に、コントローラーの寿命、スキーマ既定値、ステージサイズを確認します。ライブ出力はゲートウェイの健全性、ウィジェット認証情報、明示的欠落を調べます。ヘッドレス Chromium の成功は OBS ブラウザーソースの受け入れを証明しません。<a href="https://github.com/nglmercer/TikTools-app/tree/remake/src/widgets/sdk" target="_blank" rel="noreferrer">Widget SDK</a> と共有プロトコルテストが現行の根拠です。</p><h2 id="operational-details" tabindex="-1">運用の詳細 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;運用の詳細 {#operational-details}&quot;">​</a></h2><p>独立 unit は fixture、実 gateway Chromium は構築 widget assets と <code>TIKTOOLS_PLUGINS_REPO</code> の外部 checkout が必要です。source 不在では skip するので明示します。<code>bun x --no-install playwright test --config src/widgets/playwright.gateway.config.ts</code> を別境界として実行し、実 LIVE で OBS Browser Source・widget credential・配信・回復を確認します。headless Chromium は OBS/native 受入の証明ではありません。</p>`,15)])])}const g=a(d,[["render",o]]);export{u as __pageData,g as default};
